1	// Argument parser emulating Python argparse for the migrated script.
2	// Exposes parseArgs(argv) where argv is process.argv.slice(2).
3	
4	const PROG = "test3.mjs";
5	const USAGE = `usage: ${PROG} [-h] --a A --b B`;
6	
7	function printUsage(stream) {
8	  stream.write(USAGE + "\n");
9	}
10	
11	function fail(message) {
12	  printUsage(process.stderr);
13	  process.stderr.write(`${PROG}: error: ${message}\n`);
14	  process.exit(2);
15	}
16	
17	function printHelp() {
18	  printUsage(process.stdout);
19	  process.stdout.write("\n");
20	  process.stdout.write("options:\n");
21	  process.stdout.write("  -h, --help  show this help message and exit\n");
22	  process.stdout.write("  --a A\n");
23	  process.stdout.write("  --b B\n");
24	  process.exit(0);
25	}
26	
27	// Mirrors Python int(str): surrounding whitespace stripped, an optional
28	// sign, then decimal digits with single underscores allowed between digits.
29	function parseIntLikePython(raw, optionName) {
30	  const trimmed = raw.trim();
31	  if (!/^[+-]?\d(?:_?\d)*$/.test(trimmed)) {
32	    fail(`argument ${optionName}: invalid int value: '${raw}'`);
33	  }
34	  const negative = trimmed.startsWith("-");
35	  const digits = trimmed.replace(/^[+-]/, "").replace(/_/g, "");
36	  const value = parseInt(digits, 10);
37	  return negative ? -value : value;
38	}
