40	export function parseArgs(argv) {
41	  const values = { a: undefined, b: undefined };
42	  const seen = new Set();
43	  const unrecognized = [];
44	
45	  let i = 0;
46	  while (i < argv.length) {
47	    const token = argv[i];
48	
49	    if (token === "-h" || token === "--help") {
50	      printHelp();
51	    }
52	
53	    let name = null;
54	    let inlineValue = null;
55	
56	    if (token === "--a" || token === "--b") {
57	      name = token;
58	    } else if (token.startsWith("--a=")) {
59	      name = "--a";
60	      inlineValue = token.slice("--a=".length);
61	    } else if (token.startsWith("--b=")) {
62	      name = "--b";
63	      inlineValue = token.slice("--b=".length);
64	    }
65	
66	    if (name === null) {
67	      unrecognized.push(token);
68	      i += 1;
69	      continue;
70	    }
71	
72	    let raw;
73	    if (inlineValue !== null) {
74	      raw = inlineValue;
75	      i += 1;
76	    } else {
77	      if (i + 1 >= argv.length) {
78	        fail(`argument ${name}: expected one argument`);
79	      }
80	      raw = argv[i + 1];
81	      i += 2;
82	    }
83	
84	    const key = name === "--a" ? "a" : "b";
85	    values[key] = parseIntLikePython(raw, name);
86	    seen.add(name);
87	  }
88	
89	  const missing = [];
90	  if (!seen.has("--a")) missing.push("--a");
91	  if (!seen.has("--b")) missing.push("--b");
92	  if (missing.length > 0) {
93	    fail(`the following arguments are required: ${missing.join(", ")}`);
94	  }
95	
96	  if (unrecognized.length > 0) {
97	    fail(`unrecognized arguments: ${unrecognized.join(" ")}`);
98	  }
99	
100	  return { a: values.a, b: values.b };
101	}

1	/**
2	 * Reproduces CPython's bytes.__repr__ (what print(b'...') shows) for a
3	 * byte sequence given as a plain array of integers (each 0-255).
4	 *
5	 * Rules (matching CPython's Objects/bytesobject.c bytes_repr):
6	 * - Quote selection: single quote by default; if the data contains byte 39
7	 *   (') and does NOT contain byte 34 ("), use double quotes instead.
8	 * - Escaping, applied per byte:
9	 *     backslash (92)          -> \\
10	 *     the active quote char   -> \<quote>
11	 *     tab (9)                 -> \t
12	 *     newline (10)            -> \n
13	 *     carriage return (13)    -> \r
14	 *     bytes 32-126 (printable)-> the literal ASCII character
15	 *     all other bytes         -> \xNN (lowercase two-digit hex)
16	 * - The result is wrapped as b<quote>...<quote>.
17	 *
18	 * @param {number[]} bytes - array of integers, each in [0, 255]
19	 * @returns {string} the exact repr string CPython would produce
20	 */
21	export function bytesRepr(bytes) {
22	  const hasSingleQuote = bytes.includes(39);
23	  const hasDoubleQuote = bytes.includes(34);
24	  const quote = hasSingleQuote && !hasDoubleQuote ? 34 : 39;
25	  const quoteChar = String.fromCharCode(quote);
26	
27	  let out = 'b' + quoteChar;
28	  for (const b of bytes) {
29	    if (b === 92) {
30	      out += '\\\\';
31	    } else if (b === quote) {
32	      out += '\\' + quoteChar;
33	    } else if (b === 9) {
34	      out += '\\t';
35	    } else if (b === 10) {
36	      out += '\\n';
37	    } else if (b === 13) {
38	      out += '\\r';
39	    } else if (b >= 32 && b <= 126) {
40	      out += String.fromCharCode(b);
41	    } else {
42	      out += '\\x' + b.toString(16).padStart(2, '0');
43	    }
44	  }
45	  out += quoteChar;
46	  return out;
47	}

1	// Emulation of construct.Struct("field1"/construct.Int8ul, "field2"/construct.Int8ul).build(obj)
2	// Byte sequences are represented as plain arrays of numbers in the range 0-255.
3	
4	export const INT8UL_FIELDS = [
5	  { name: 'field1', min: 0, max: 255 },
6	  { name: 'field2', min: 0, max: 255 },
7	];
8	
9	export function buildStruct(obj) {
10	  const result = [];
11	  for (const field of INT8UL_FIELDS) {
12	    const value = obj[field.name];
13	    if (
14	      typeof value !== 'number' ||
15	      !Number.isInteger(value) ||
16	      value < field.min ||
17	      value > field.max
18	    ) {
19	      throw new RangeError(
20	        `Error in path (building) -> ${field.name}\nstruct '<B' error during building, given value ${value}`
21	      );
22	    }
23	    result.push(value);
24	  }
25	  return result;
26	}

